10	interface Props {
11	  identityProviderList: IdentityProvider[];
12	  redirectTarget?: string;
13	}
14	
15	const IdentityProviderButtons = ({ identityProviderList, redirectTarget }: Props) => {
16	  const t = useTranslate();
17	
18	  const handleSignInWithIdentityProvider = async (identityProvider: IdentityProvider) => {
19	    if (identityProvider.type === IdentityProvider_Type.OAUTH2) {
20	      const redirectUri = absolutifyLink(ROUTES.AUTH_CALLBACK);
21	      const oauth2Config = identityProvider.config?.config?.case === "oauth2Config" ? identityProvider.config.config.value : undefined;
22	      if (!oauth2Config) {
23	        toast.error("Identity provider configuration is invalid.");
24	        return;
25	      }
26	
27	      try {
28	        // Generate and store secure state parameter with CSRF protection
29	        // Also generate PKCE parameters (code_challenge) for enhanced security if available
30	        const { state, codeChallenge } = await storeOAuthState(identityProvider.name, "signin", redirectTarget);
31	
32	        // Build OAuth authorization URL with secure state
33	        // Include PKCE if available (requires HTTPS/localhost for crypto.subtle)
34	        // Using S256 (SHA-256) as the code_challenge_method per RFC 7636
35	        let authUrl = `${oauth2Config.authUrl}?client_id=${
36	          oauth2Config.clientId
37	        }&redirect_uri=${encodeURIComponent(redirectUri)}&state=${state}&response_type=code&scope=${encodeURIComponent(
38	          oauth2Config.scopes.join(" "),
39	        )}`;
40	
41	        // Add PKCE parameters if available
42	        if (codeChallenge) {
43	          authUrl += `&code_challenge=${codeChallenge}&code_challenge_method=S256`;
44	        }
45	
46	        window.location.href = authUrl;
47	      } catch (error) {
48	        handleError(error, toast.error, {
49	          context: "Failed to initiate OAuth flow",
50	          fallbackMessage: "Failed to initiate sign-in. Please try again.",
51	        });
52	      }
53	    }
54	  };
55	
56	  return (
57	    <div className="flex w-full flex-col gap-2">
58	      {identityProviderList.map((identityProvider) => (
59	        <Button key={identityProvider.name} variant="outline" onClick={() => handleSignInWithIdentityProvider(identityProvider)}>
60	          {t("auth.continue-with", { provider: identityProvider.title })}
61	        </Button>
62	      ))}
63	    </div>
64	  );
65	};
66	
67	export default IdentityProviderButtons;
